head.b:skin:
/* ==========================================================================
   MEIWASPORTS - THE ULTIMATE LIVE STREAMING PORTAL (XOILAC/SOCOLIVE PRO STYLE)
   ========================================================================== */
:root {
  --bg-dark: #080c14;
  --bg-card: #101726;
  --bg-card-hover: #172238;
  --bg-surface: #192338;
  --bg-header: #070a10;

  --primary-green: #10b981;
  --primary-neon: #00eb1f;
  --primary-glow: rgba(16, 185, 129, 0.35);

  --accent-gold: #ffe400;
  --accent-red: #ef4444;
  --accent-red-glow: rgba(239, 68, 68, 0.4);
  --accent-blue: #3b82f6;
  --saweria-green: #22c55e;

  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --text-dim: #64748b;

  --border-subtle: rgba(255, 255, 255, 0.08);
  --border-hover: rgba(16, 185, 129, 0.5);
  --border-gold: rgba(255, 228, 0, 0.4);

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-full: 9999px;

  --font-main: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-heading: 'Outfit', sans-serif;
  --transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg-dark);
  color: var(--text-main);
  font-family: var(--font-main);
  font-size: 14px;
  line-height: 1.5;
  min-height: 100vh;
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
  transition: var(--transition);
}

/* TOP NAVBAR */
.site-header {
  background: var(--bg-header);
  border-bottom: 1px solid var(--border-subtle);
  position: sticky;
  top: 0;
  z-index: 1000;
  backdrop-filter: blur(12px);
}

.nav-container {
  max-width: 1440px;
  margin: 0 auto;
  padding: 0 16px;
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.brand-logo {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: linear-gradient(135deg, #101726, #1c2840);
  padding: 6px 14px;
  border-radius: 10px;
  border: 1px solid var(--border-subtle);
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.4);
  text-decoration: none;
}
.brand-logo:hover {
  border-color: var(--primary-green);
  box-shadow: 0 4px 20px var(--primary-glow);
}
.brand-logo-img {
  height: 32px;
  width: auto;
  object-fit: contain;
  display: block;
}

.nav-menu-links {
  display: flex;
  align-items: center;
  gap: 6px;
  list-style: none;
}

.nav-item-btn {
  padding: 8px 14px;
  font-size: 13px;
  font-weight: 700;
  color: var(--text-muted);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  gap: 6px;
  transition: var(--transition);
}
.nav-item-btn:hover {
  color: #fff;
  background: rgba(255, 255, 255, 0.06);
}
.nav-item-btn.active {
  color: #000;
  background: var(--primary-green);
  box-shadow: 0 2px 10px var(--primary-glow);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.btn-saweria-top {
  background: linear-gradient(135deg, #eab308, #ca8a04);
  color: #000;
  font-weight: 800;
  font-size: 12px;
  padding: 8px 14px;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  gap: 6px;
  box-shadow: 0 2px 12px rgba(234, 179, 8, 0.35);
  transition: var(--transition);
}
.btn-saweria-top:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 16px rgba(234, 179, 8, 0.5);
  color: #000;
}

.btn-apk-top {
  background: linear-gradient(135deg, #10b981, #059669);
  color: #000;
  font-weight: 800;
  font-size: 12px;
  padding: 8px 14px;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  gap: 6px;
  box-shadow: 0 2px 12px var(--primary-glow);
  transition: var(--transition);
}
.btn-apk-top:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 16px var(--primary-glow);
  color: #000;
}

/* TOP PROMO & ADSTERRA BANNER */
.adsterra-banner-container {
  max-width: 1440px;
  margin: 12px auto;
  padding: 0 16px;
  text-align: center;
}
.adsterra-wrapper-box {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 90px;
}

/* MAIN STADIUM LAYOUT */
.stadium-container {
  max-width: 1440px;
  margin: 10px auto 40px auto;
  padding: 0 16px;
  display: grid;
  grid-template-columns: 1fr 400px;
  gap: 20px;
  align-items: start;
}

@media (max-width: 1024px) {
  .stadium-container {
    grid-template-columns: 1fr;
  }
  .nav-menu-links {
    display: none;
  }
}

/* LEFT: HERO BROADCAST PLAYER STAGE */
.stadium-left {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.hero-player-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.6);
}

.player-top-bar {
  background: #090d16;
  padding: 10px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--border-subtle);
  flex-wrap: wrap;
  gap: 8px;
}

.player-match-badge {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 700;
}
.live-indicator {
  background: rgba(239, 68, 68, 0.15);
  color: var(--accent-red);
  border: 1px solid rgba(239, 68, 68, 0.4);
  padding: 3px 10px;
  border-radius: var(--radius-full);
  font-size: 11px;
  font-weight: 800;
  display: flex;
  align-items: center;
  gap: 6px;
  animation: livePulse 1.8s infinite;
}
@keyframes livePulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.4); }
  50% { box-shadow: 0 0 10px 2px rgba(239, 68, 68, 0.2); }
}

.player-server-group {
  display: flex;
  align-items: center;
  gap: 6px;
}

.btn-server {
  background: var(--bg-surface);
  color: var(--text-muted);
  border: 1px solid var(--border-subtle);
  padding: 6px 14px;
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 6px;
  transition: var(--transition);
}
.btn-server:hover {
  color: #fff;
  border-color: var(--primary-green);
}
.btn-server.active {
  background: var(--primary-green);
  color: #000;
  border-color: var(--primary-green);
  box-shadow: 0 0 12px var(--primary-glow);
}

.video-container-169 {
  position: relative;
  width: 100%;
  padding-top: 56.25%; /* 16:9 Ratio */
  background: #000;
}
.video-container-169 video,
.video-container-169 iframe {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  border: none;
  background: #000;
}

/* PLAYER OVERLAY & OVERVIEW */
.player-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: radial-gradient(circle at center, rgba(16, 23, 38, 0.96), rgba(8, 12, 20, 0.98));
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 24px;
  text-align: center;
  gap: 12px;
  z-index: 10;
  backdrop-filter: blur(8px);
}

.player-overlay-league {
  color: var(--primary-green);
  font-size: 12px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 1px;
}
.player-overlay-title {
  font-family: var(--font-heading);
  font-size: 22px;
  font-weight: 800;
  color: #fff;
  line-height: 1.2;
}
.player-overlay-time {
  font-size: 13px;
  color: var(--text-muted);
}
.player-overlay-time b {
  color: var(--accent-gold);
}
.player-overlay-actions {
  display: flex;
  gap: 10px;
  margin-top: 6px;
  flex-wrap: wrap;
  justify-content: center;
}
.btn-overlay-play {
  background: linear-gradient(135deg, #10b981, #059669);
  color: #000;
  font-weight: 800;
  font-size: 13px;
  padding: 10px 22px;
  border-radius: var(--radius-full);
  border: none;
  cursor: pointer;
  box-shadow: 0 4px 15px var(--primary-glow);
  display: flex;
  align-items: center;
  gap: 8px;
  transition: var(--transition);
}
.btn-overlay-play:hover {
  transform: scale(1.04);
}

/* MATCH INFO DETAILS BAR UNDER PLAYER */
.player-match-detail-bar {
  padding: 16px 20px;
  background: #090d16;
  border-top: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 14px;
}
.detail-match-teams {
  display: flex;
  align-items: center;
  gap: 14px;
  font-family: var(--font-heading);
  font-size: 17px;
  font-weight: 800;
}
.detail-team-logo {
  width: 32px;
  height: 32px;
  object-fit: contain;
}
.detail-score-pill {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  color: var(--accent-gold);
  padding: 4px 12px;
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 800;
}

/* DONATION & APK PROMO CARDS (UNDER PLAYER) */
.left-promo-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}
@media (max-width: 640px) {
  .left-promo-grid {
    grid-template-columns: 1fr;
  }
}
.promo-banner-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: 14px 18px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.promo-banner-card.saweria {
  border-color: rgba(234, 179, 8, 0.3);
  background: linear-gradient(135deg, rgba(234, 179, 8, 0.08), rgba(202, 138, 4, 0.02));
}
.promo-banner-card.apk {
  border-color: rgba(16, 185, 129, 0.3);
  background: linear-gradient(135deg, rgba(16, 185, 129, 0.08), rgba(5, 150, 105, 0.02));
}

/* RIGHT: MATCH SCHEDULE LIST & MULTI-SPORT TABS */
.stadium-right {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.schedule-panel {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  display: flex;
  flex-direction: column;
  height: 780px;
  overflow: hidden;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
}

/* SEARCH & SPORT TABS */
.schedule-header-controls {
  background: #090d16;
  padding: 12px 14px 8px 14px;
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.search-box-wrap {
  position: relative;
  width: 100%;
}
.search-input {
  width: 100%;
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  color: #fff;
  font-size: 13px;
  padding: 8px 12px 8px 34px;
  border-radius: var(--radius-sm);
  outline: none;
  transition: var(--transition);
}
.search-input:focus {
  border-color: var(--primary-green);
  box-shadow: 0 0 10px var(--primary-glow);
}
.search-icon {
  position: absolute;
  left: 11px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-dim);
  font-size: 13px;
}

.sports-chips-nav {
  display: flex;
  gap: 6px;
  overflow-x: auto;
  scrollbar-width: none;
  -webkit-overflow-scrolling: touch;
  padding-bottom: 4px;
}
.sports-chips-nav::-webkit-scrollbar {
  display: none;
}

.sport-chip {
  white-space: nowrap;
  padding: 6px 12px;
  font-size: 12px;
  font-weight: 700;
  color: var(--text-muted);
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-full);
  cursor: pointer;
  transition: var(--transition);
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.sport-chip:hover {
  color: #fff;
  border-color: rgba(255, 255, 255, 0.25);
  background: rgba(255, 255, 255, 0.08);
}
.sport-chip.active {
  color: #000;
  background: var(--primary-green);
  border-color: var(--primary-green);
  box-shadow: 0 2px 10px var(--primary-glow);
}
.sport-chip.chip-live.active {
  color: #fff;
  background: var(--accent-red);
  border-color: var(--accent-red);
  box-shadow: 0 2px 10px var(--accent-red-glow);
}
.chip-count {
  background: rgba(0, 0, 0, 0.3);
  padding: 1px 6px;
  border-radius: var(--radius-full);
  font-size: 10px;
  font-weight: 800;
}

/* MATCH CARDS LIST (XOILAC / SOCOLIVE STYLE) */
.match-scroll-feed {
  flex: 1;
  overflow-y: auto;
  padding: 10px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.match-scroll-feed::-webkit-scrollbar {
  width: 6px;
}
.match-scroll-feed::-webkit-scrollbar-thumb {
  background: var(--bg-surface);
  border-radius: 4px;
}

.match-card-item {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  cursor: pointer;
  transition: var(--transition);
}
.match-card-item:hover, .match-card-item.active {
  background: var(--bg-card-hover);
  border-color: var(--primary-green);
  transform: translateY(-2px);
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.4);
}

.match-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 11.5px;
  color: var(--text-muted);
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
  padding-bottom: 6px;
}
.match-league-title {
  font-weight: 700;
  color: var(--primary-green);
  display: flex;
  align-items: center;
  gap: 6px;
  text-transform: uppercase;
  letter-spacing: 0.3px;
}
.match-time-tag {
  font-size: 11px;
  color: var(--text-dim);
}

.match-card-body {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.team-side {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13.5px;
  font-weight: 700;
  color: #fff;
}
.team-side.away {
  justify-content: flex-end;
  text-align: right;
}
.card-team-logo {
  width: 26px;
  height: 26px;
  object-fit: contain;
}

.match-center-score {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  min-width: 68px;
}
.score-badge-live {
  background: #000;
  color: var(--accent-gold);
  border: 1px solid var(--border-gold);
  font-family: var(--font-heading);
  font-size: 14px;
  font-weight: 800;
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  letter-spacing: 1px;
}
.live-dot-tag {
  color: var(--accent-red);
  font-size: 10px;
  font-weight: 800;
  display: flex;
  align-items: center;
  gap: 4px;
}

/* CARD ACTION CHANNELS */
.match-card-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  padding-top: 6px;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
}
.stream-btn-chip {
  flex: 1;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--border-subtle);
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 700;
  padding: 4px 6px;
  border-radius: var(--radius-sm);
  text-align: center;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  transition: var(--transition);
}
.stream-btn-chip:hover {
  background: var(--primary-green);
  color: #000;
  border-color: var(--primary-green);
}

/* FOOTER */
.site-footer {
  background: #06090f;
  border-top: 1px solid var(--border-subtle);
  padding: 30px 20px;
  text-align: center;
  font-size: 12px;
  color: var(--text-dim);
}
.site-footer a {
  color: var(--primary-green);
}

/* HIDE UNWANTED BLOGGER STUFF */
.post-hidden-meta,
.event-link-preview,
.match-source-link {
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
}

