let allLoadedMatches = [...AUTO_LIVE_DATASET]; let currentCategoryFilter = "all"; let currentSearchKeyword = "";
// 1. SPORT CATEGORY METADATA HELPER function getSportCategoryMeta(catString, title, league) { const text = (catString + ' ' + title + ' ' + league).toLowerCase(); if (text.includes('basket') || text.includes('bóng rổ') || text.includes('nba')) { return { icon: '🏀', name: 'Basket', key: 'basketball' }; } if (text.includes('tenis') || text.includes('tennis') || text.includes('atp') || text.includes('wta')) { return { icon: '🎾', name: 'Tenis', key: 'tennis' }; } if (text.includes('voli') || text.includes('volleyball') || text.includes('bóng chuyền')) { return { icon: '🏐', name: 'Voli', key: 'volleyball' }; } if (text.includes('badminton') || text.includes('cầu lông') || text.includes('bwf')) { return { icon: '🏸', name: 'Badminton', key: 'badminton' }; } if (text.includes('esport') || text.includes('dota') || text.includes('league of legends') || text.includes('pubg')) { return { icon: '🎮', name: 'Esports', key: 'esports' }; } return { icon: '⚽', name: 'Sepak Bola', key: 'football' }; }
// 2. RENDER MATCH LIST WITH RICH CARDS (XOILAC / SOCOLIVE STYLE) function renderMatchList(matchesToRender) { allLoadedMatches = matchesToRender || AUTO_LIVE_DATASET; updateCategoryBadges(allLoadedMatches);
const scrollFeed = document.getElementById('matchScrollList'); if (!scrollFeed) return;
let filtered = allLoadedMatches.filter(m => { const sportMeta = getSportCategoryMeta(m.sportCategory || '', m.title || '', m.league || ''); const isLive = m.status === 1 || (m.scoreText && m.scoreText.includes('-') && m.status !== 2); const isFinished = m.status === 2 || (m.scoreText && m.scoreText.includes('FT')); const isUpcoming = !isLive && !isFinished;
// Category matching if (currentCategoryFilter === 'live' && !isLive) return false; if (currentCategoryFilter === 'upcoming' && !isUpcoming) return false; if (currentCategoryFilter === 'finished' && !isFinished) return false; if (['football', 'basketball', 'tennis', 'volleyball', 'badminton', 'esports'].includes(currentCategoryFilter)) { if (sportMeta.key !== currentCategoryFilter) return false; }
// Search keyword matching if (currentSearchKeyword.trim() !== '') { const query = currentSearchKeyword.toLowerCase().trim(); const searchTarget = (m.title + ' ' + (m.homeTeam || '') + ' ' + (m.awayTeam || '') + ' ' + (m.league || '')).toLowerCase(); if (!searchTarget.includes(query)) return false; }
return true; });
if (filtered.length === 0) { scrollFeed.innerHTML = ` <div style="text-align:center; padding:40px 20px; color:var(--text-muted);"> <i class="fa-solid fa-calendar-xmark fa-2x" style="color:var(--text-dim); margin-bottom:10px;"></i> <p style="font-weight:700;">Tidak ada pertandingan ditemukan</p> <p style="font-size:12px; color:var(--text-dim);">Silakan pilih cabang olahraga lain atau ubah kata kunci pencarian.</p> </div>`; return; }
let html = ''; filtered.forEach((match, idx) => { const sportMeta = getSportCategoryMeta(match.sportCategory || '', match.title || '', match.league || ''); const isLive = match.status === 1 || (match.scoreText && match.scoreText.includes('-') && match.status !== 2); const homeName = match.homeTeam || match.title.split(' vs ')[0] || 'Tuan Rumah'; const awayName = match.awayTeam || match.title.split(' vs ')[1] || 'Tamu'; const homeLogo = match.homeLogo || 'https://raw.githubusercontent.com/adityafarid0112/meiwatv/main/Logo%20Meiwa%20icon.png'; const awayLogo = match.awayLogo || 'https://raw.githubusercontent.com/adityafarid0112/meiwatv/main/Logo%20Meiwa%20icon.png';
const scoreDisplay = match.scoreText || (isLive ? '0 - 0' : 'VS'); const statusLabel = isLive ? `<span class="live-dot-tag"><i class="fa-solid fa-circle fa-2xs"></i> LIVE ${match.matchMinute ? match.matchMinute : ''}</span>` : `<span style="color:var(--text-dim); font-size:10.5px;">${match.kickoffText || 'Siap Tayang'}</span>`;
const activeClass = (currentActiveMatch && currentActiveMatch.title === match.title) ? ' active' : '';
html += ` <div class="match-card-item${activeClass}" onclick="selectMatchCard(${idx})" id="match-item-${idx}"> <div class="match-card-header"> <span class="match-league-title"> <span>${sportMeta.icon}</span> <span>${match.league || 'Sport Match'}</span> </span> <span class="match-time-tag"><i class="fa-regular fa-clock"></i> ${match.kickoffText || ''}</span> </div>
<div class="match-card-body"> <div class="team-side"> <img src="${homeLogo}" alt="${homeName}" class="card-team-logo" onerror="this.src='https://raw.githubusercontent.com/adityafarid0112/meiwatv/main/Logo%20Meiwa%20icon.png'"/> <span>${homeName}</span> </div>
<div class="match-center-score"> <div class="score-badge-live">${scoreDisplay}</div> ${statusLabel} </div>
<div class="team-side away"> <span>${awayName}</span> <img src="${awayLogo}" alt="${awayName}" class="card-team-logo" onerror="this.src='https://raw.githubusercontent.com/adityafarid0112/meiwatv/main/Logo%20Meiwa%20icon.png'"/> </div> </div>
<div class="match-card-actions" onclick="event.stopPropagation();"> <button class="stream-btn-chip" onclick="playMatchDirect(${idx}, 1)" type="button"> <i class="fa-solid fa-play fa-xs" style="color:var(--primary-green);"></i> <span>Jalur 1 (HD)</span> </button> <button class="stream-btn-chip" onclick="playMatchDirect(${idx}, 2)" type="button"> <i class="fa-solid fa-bolt fa-xs" style="color:var(--accent-gold);"></i> <span>Jalur 2 (FHD)</span> </button> <button class="stream-btn-chip" onclick="playMatchDirect(${idx}, 3)" type="button"> <i class="fa-solid fa-server fa-xs"></i> <span>Jalur 3</span> </button> </div> </div> `; });
scrollFeed.innerHTML = html;
// Default select first match if not selected yet if (!currentActiveMatch && filtered.length > 0) { setHeroMatchPreview(filtered[0]); } }
// 3. UPDATE CATEGORY BADGE COUNTERS function updateCategoryBadges(matches) { let counts = { all: matches.length, live: 0, football: 0, basketball: 0, tennis: 0, volleyball: 0, badminton: 0, esports: 0, upcoming: 0 }; matches.forEach(m => { const isLive = m.status === 1 || (m.scoreText && m.scoreText.includes('-') && m.status !== 2); if (isLive) counts.live++; else counts.upcoming++;
const meta = getSportCategoryMeta(m.sportCategory || '', m.title || '', m.league || ''); if (counts[meta.key] !== undefined) counts[meta.key]++; });
for (const key in counts) { const el = document.getElementById('count' + key.charAt(0).toUpperCase() + key.slice(1)); if (el) el.textContent = counts[key]; } }
// 4. FILTER MATCHES BY SPORT function filterMatchesBySport(category, btnElement) { currentCategoryFilter = category; document.querySelectorAll('.sport-chip').forEach(el => el.classList.remove('active')); if (btnElement) btnElement.classList.add('active'); renderMatchList(allLoadedMatches); }
// 5. SEARCH HANDLER function handleMatchSearch(keyword) { currentSearchKeyword = keyword; renderMatchList(allLoadedMatches); }
// 6. SELECT MATCH CARD & SET PREVIEW function selectMatchCard(index) { const match = allLoadedMatches[index]; if (!match) return; setHeroMatchPreview(match); playMatchDirect(index, 1); }
function setHeroMatchPreview(match) { currentActiveMatch = match; activeStreamUrlServer1 = match.streamUrl || match.streamJalur1 || ''; activeStreamUrlServer2 = match.server2Url || match.streamJalur2 || ''; activeStreamUrlServer3 = match.streamJalur3 || match.postUrl || '';
// Update Player Stage details const leagueEl = document.getElementById('playerLeagueText'); if (leagueEl) leagueEl.textContent = match.league || 'Sport Match';
const overlayLeague = document.getElementById('overlayLeague'); if (overlayLeague) overlayLeague.textContent = match.league || 'Sport Match';
const overlayTitle = document.getElementById('overlayTitle'); if (overlayTitle) overlayTitle.textContent = match.title;
const overlayKickoff = document.getElementById('overlayKickoff'); if (overlayKickoff) overlayKickoff.innerHTML = 'Jadwal Kick-off: <b>' + (match.kickoffText || 'Siap Tayang') + '</b>';
const homeNameEl = document.getElementById('detailHomeTeam'); if (homeNameEl) homeNameEl.textContent = match.homeTeam || match.title.split(' vs ')[0] || 'Tuan Rumah';
const awayNameEl = document.getElementById('detailAwayTeam'); if (awayNameEl) awayNameEl.textContent = match.awayTeam || match.title.split(' vs ')[1] || 'Tamu';
const scoreEl = document.getElementById('detailScore'); if (scoreEl) scoreEl.textContent = match.scoreText || 'VS';
const homeLogoEl = document.getElementById('detailHomeLogo'); if (homeLogoEl) homeLogoEl.src = match.homeLogo || 'https://raw.githubusercontent.com/adityafarid0112/meiwatv/main/Logo%20Meiwa%20icon.png';
const awayLogoEl = document.getElementById('detailAwayLogo'); if (awayLogoEl) awayLogoEl.src = match.awayLogo || 'https://raw.githubusercontent.com/adityafarid0112/meiwatv/main/Logo%20Meiwa%20icon.png'; }
// 7. PLAY MATCH DIRECTLY (STREAM ENGINE) function playMatchDirect(index, serverIndex) { const match = allLoadedMatches[index]; if (match) setHeroMatchPreview(match); activeCurrentServer = serverIndex || 1;
// Trigger Adsterra popunder monetization triggerAdsterra();
// Scroll smoothly to player const playerCard = document.getElementById('playerSection'); if (playerCard) { playerCard.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
// Hide Overlay const overlay = document.getElementById('playerOverlay'); if (overlay) overlay.style.display = 'none';
// Update server buttons active state document.querySelectorAll('.btn-server').forEach((btn, idx) => { if (idx + 1 === activeCurrentServer) btn.classList.add('active'); else btn.classList.remove('active'); });
let targetStreamUrl = activeStreamUrlServer1; if (activeCurrentServer === 2 && activeStreamUrlServer2) targetStreamUrl = activeStreamUrlServer2; if (activeCurrentServer === 3 && activeStreamUrlServer3) targetStreamUrl = activeStreamUrlServer3;
executeStreamPlayback(targetStreamUrl); }
function triggerOverlayPlay() { if (currentActiveMatch) { playMatchDirect(allLoadedMatches.indexOf(currentActiveMatch), 1); } else if (allLoadedMatches.length > 0) { playMatchDirect(0, 1); } }
function switchServer(serverIdx) { activeCurrentServer = serverIdx; triggerAdsterra();
document.querySelectorAll('.btn-server').forEach((btn, idx) => { if (idx + 1 === activeCurrentServer) btn.classList.add('active'); else btn.classList.remove('active'); });
let targetStreamUrl = activeStreamUrlServer1; if (activeCurrentServer === 2 && activeStreamUrlServer2) targetStreamUrl = activeStreamUrlServer2; if (activeCurrentServer === 3 && activeStreamUrlServer3) targetStreamUrl = activeStreamUrlServer3;
executeStreamPlayback(targetStreamUrl); }
// 8. EXECUTE VIDEO STREAM PLAYBACK (HLS / FLV / IFRAME) function executeStreamPlayback(streamUrl) { const video = document.getElementById('mainVideoPlayer'); const iframe = document.getElementById('mainIframePlayer');
if (!streamUrl || streamUrl === '#' || streamUrl.trim() === '') { console.warn('Empty stream URL, using backup iframe'); if (video) video.style.display = 'none'; if (iframe) { iframe.style.display = 'block'; iframe.src = activeStreamUrlServer3 || 'about:blank'; } return; }
// Clean previous instances if (hlsInstance) { hlsInstance.destroy(); hlsInstance = null; } if (flvPlayerInstance) { flvPlayerInstance.destroy(); flvPlayerInstance = null; }
const isDirectFlv = streamUrl.includes('.flv') || streamUrl.includes('type=flv') || streamUrl.includes('type/7') || streamUrl.includes('type/8'); const isDirectM3u8 = streamUrl.includes('.m3u8') || streamUrl.includes('type=m3u8') || streamUrl.includes('type/5');
if (isDirectFlv && typeof flvjs !== 'undefined' && flvjs.isSupported()) { if (iframe) iframe.style.display = 'none'; if (video) { video.style.display = 'block'; try { flvPlayerInstance = flvjs.createPlayer({ type: 'flv', url: streamUrl, isLive: true, cors: true }); flvPlayerInstance.attachMediaElement(video); flvPlayerInstance.load(); video.play().catch(() => {}); } catch (e) { console.warn('FLV fallback to iframe:', e); fallbackToIframe(streamUrl); } } } else if (isDirectM3u8 && typeof Hls !== 'undefined' && Hls.isSupported()) { if (iframe) iframe.style.display = 'none'; if (video) { video.style.display = 'block'; try { hlsInstance = new Hls({ enableWorker: true, lowLatencyMode: true }); hlsInstance.loadSource(streamUrl); hlsInstance.attachMedia(video); hlsInstance.on(Hls.Events.MANIFEST_PARSED, function() { video.play().catch(() => {}); }); } catch (e) { console.warn('HLS fallback to iframe:', e); fallbackToIframe(streamUrl); } } } else { fallbackToIframe(streamUrl); } }
function fallbackToIframe(url) { const video = document.getElementById('mainVideoPlayer'); const iframe = document.getElementById('mainIframePlayer'); if (video) { video.pause(); video.style.display = 'none'; } if (iframe) { iframe.style.display = 'block'; iframe.src = url; } }
function shareCurrentMatch() { if (navigator.share && currentActiveMatch) { navigator.share({ title: currentActiveMatch.title + ' - Live Streaming MeiwaSports', url: window.location.href }).catch(() => {}); } else { navigator.clipboard.writeText(window.location.href); alert('Link pertandingan berhasil disalin!'); } }
// 9. AUTOMATIC REAL-TIME SYNC VIA GITHUB RAW & CDN function fetchLiveMatchesDirect() { const syncSources = [ 'https://raw.githubusercontent.com/adityafarid0112/meiwatv/main/matches.json', 'https://cdn.jsdelivr.net/gh/adityafarid0112/meiwatv@main/matches.json' ];
function tryFetchSource(idx) { if (idx >= syncSources.length) return; fetch(syncSources[idx] + '?_t=' + Date.now()) .then(res => { if (!res.ok) throw new Error('Sync source failed'); return res.json(); }) .then(data => { if (Array.isArray(data) && data.length > 0) { console.log('✅ Real-time matches synced successfully:', data.length); renderMatchList(data); } }) .catch(err => { tryFetchSource(idx + 1); }); }
tryFetchSource(0); }
// 10. INIT ON DOM LOAD function initLivePortal() { renderMatchList(AUTO_LIVE_DATASET);
// Initial background sync after 4 seconds setTimeout(function() { fetchLiveMatchesDirect(); setInterval(fetchLiveMatchesDirect, 120000); }, 4000); }
document.addEventListener('DOMContentLoaded', initLivePortal); //
